'use strict';
const $ = (s, root = document) => root.querySelector(s);
const $$ = (s, root = document) => [...root.querySelectorAll(s)];
const escapeHTML = s => String(s).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon = (name, cls = 'h-[18px] w-[18px]') => `<i data-lucide="${name}" class="${cls}" aria-hidden="true"></i>`;
const primary = 'tactile inline-flex min-h-12 items-center justify-center gap-2 rounded-xl bg-ink px-4 text-sm font-semibold text-lime disabled:opacity-40';
const secondary = 'tactile inline-flex min-h-11 items-center justify-center gap-2 rounded-xl border border-line bg-white px-4 text-[13px] font-medium';
const photo = '../images/generated.png';
const races = {
  brooklyn: {name:'Brooklyn Half', city:'Brooklyn, New York', shortCity:'Brooklyn', distance:'Half marathon', km:'21.1 km', date:'May 16, 2027', lottery:true, photo:true, closes:'Oct 16, 2026', time:'5:00 PM', opens:'Oct 2, 2026', results:'Oct 28, 2026', story:'21.1 km of Brooklyn streets, neighborhood energy and a finish line worth sharing.'},
  bridges: {name:'City Bridges 10K', city:'New York', shortCity:'New York', distance:'10K', km:'10 km', date:'Apr 11, 2027', lottery:false, photo:true, closes:'Nov 20, 2026', time:'5:00 PM', opens:'Nov 2, 2026', story:'A shorter city run with a big sense of occasion. Ten kilometers and a good reason to bring your running buddy.'},
  hudson: {name:'Hudson Trails', city:'Hudson Valley', shortCity:'Hudson Valley', distance:'Trail & ultra', km:'25 km', date:'Apr 24, 2027', lottery:false, photo:false, closes:'Nov 25, 2026', time:'5:00 PM', opens:'Nov 8, 2026', story:'A change of pace and a little fresh air. Twenty-five kilometers to look forward to with your favorite running company.'}
};
let stored = {};
try { stored = JSON.parse(localStorage.getItem('race-poke-prototype-v1') || '{}'); } catch {}
const state = { route: new URLSearchParams(location.search).has('race') ? 'detail' : 'home', tab:'Overview', race:races[new URLSearchParams(location.search).get('race')] ? new URLSearchParams(location.search).get('race') : 'brooklyn', records:stored.records || {}, motion:stored.motion || false, moment:0, month:9, year:2026, day:16, search:'', distance:'Any distance', city:'New York', step:0, onboardDistances:['10K','Half marathon'], modal:null, draft:[], justPoked:null };
const record = (key=state.race) => state.records[key] || {dates:[],saved:false,going:false};
const race = () => races[state.race];
const save = () => { try { localStorage.setItem('race-poke-prototype-v1',JSON.stringify({records:state.records,motion:state.motion})); } catch {} };
const patch = (data,key=state.race) => {state.records[key]={...record(key),...data}; save();};
const reduceQuery = matchMedia('(prefers-reduced-motion: reduce)');
const reduced = () => state.motion || reduceQuery.matches;
let changing = false, transitionTimer, toastTimer, lastFocus, closeTimer;
let observer;
function applyMotion() { document.documentElement.dataset.motion = state.motion ? 'reduce':'system'; $('#motion-setting').checked=state.motion; }
applyMotion();
function refreshIcons() { if(window.lucide) lucide.createIcons(); }
function activateReveals() { observer?.disconnect(); observer = new IntersectionObserver(entries => entries.forEach(e => {if(e.isIntersecting){e.target.classList.add('in-view');observer.unobserve(e.target);}}),{root:$('#screen'),threshold:.12}); $$('.reveal').forEach(el => reduced()?el.classList.add('in-view'):observer.observe(el)); }
function bindVisuals() {refreshIcons();activateReveals();}
function route(next, opts={}) { if(changing) return; clearTimeout(toastTimer);$('#toast').hidden=true;$('#toast').classList.remove('visible');closeSheet(false); changing=true; $('#view').classList.add('leaving'); clearTimeout(transitionTimer); transitionTimer=setTimeout(()=>{state.route=next;if(opts.race)state.race=opts.race;if(opts.tab)state.tab=opts.tab;render();$('#screen').scrollTop=0;$('#view').classList.add('arriving');$('#view').classList.remove('leaving');$('#view h1, #view h2')?.focus({preventScroll:true});changing=false;},reduced()?0:110); }
function toast(message) {clearTimeout(toastTimer);const el=$('#toast');el.innerHTML=icon('check','h-4 w-4 shrink-0')+`<span>${escapeHTML(message)}</span>`;el.hidden=false;refreshIcons();requestAnimationFrame(()=>el.classList.add('visible'));toastTimer=setTimeout(()=>{el.classList.remove('visible');setTimeout(()=>el.hidden=true,reduced()?0:200);},3200);}
function appHeader() {return `<header class="flex items-center justify-between py-5"><span class="text-[22px] font-extrabold tracking-tight">race poke.</span><div class="flex items-center gap-2"><button class="min-h-11 px-2 text-xs text-muted" data-action="nav" data-route="saved">Your saved races →</button><button class="flex h-11 w-11 items-center justify-center" aria-label="Demo settings" data-action="settings">${icon('ellipsis')}</button></div></header>`;}
function pokeButton(key, cls='w-full', label='Poke Me') {const r=record(key),poked=r.dates.length>0;return `<button class="poke-button ${primary} ${cls} ${poked?'!bg-soft !text-ink':''} ${state.justPoked===key?'just-poked':''}" data-action="poke" data-race="${key}" aria-label="${poked?'Edit reminders for':'Poke'} ${races[key].name}">${icon(poked?'check':'bell-plus',`h-[18px] w-[18px] ${poked?'check-mark':''}`)}<span>${poked?'Poked':label}</span></button>`;}
function nextMoment(key='brooklyn') {const r=races[key],rec=record(key);if(rec.going)return 'You’re going. See you at the start line.';if(state.moment&&r.lottery)return `Results day ${r.results.replace(', 2026','')} · Time to come`;return `Entry closes ${r.closes.replace(', 2026','')} · ${r.time.replace(':00','')} ET`;}
function home() {const r=races.brooklyn;return `<div class="px-4 pb-6">${appHeader()}<h1 tabindex="-1" class="mt-2 text-[30px] leading-[1.1] tracking-tight">Something to<br>look forward to.</h1><p class="mb-6 mt-3 text-[13px] text-muted">You pick the race. We’ll watch the dates.</p>
<label class="flex min-h-12 items-center gap-3 rounded-xl border border-line bg-white px-4">${icon('search')}<input id="race-search" type="search" value="${escapeHTML(state.search)}" placeholder="Search races or a city" aria-label="Search races or a city" class="min-w-0 flex-1 bg-transparent text-sm outline-none"></label>
<div class="mt-3 flex gap-2"><button data-action="city-filter" class="${secondary} flex-1 !bg-soft">${icon('map-pin','h-4 w-4')}${escapeHTML(state.city)}</button><button data-action="distance-filter" class="${secondary} flex-1">${icon('sliders-horizontal','h-4 w-4')}${state.distance==='Any distance'?'Distance':state.distance}</button></div>
<div id="home-results">${homeResults()}</div></div>`;}
function homeResults(){const keys=Object.keys(races).filter(k=>(races[k].name+' '+races[k].city).toLowerCase().includes(state.search.toLowerCase())&&(state.distance==='Any distance'||races[k].distance===state.distance));if(!keys.length)return `<div class="py-16"><h2 class="text-xl">No start lines here yet.</h2><p class="mt-3 text-sm text-muted">Try another name or a different distance.</p><button class="${secondary} mt-5" data-action="clear-search">Show all races</button></div>`;const featured=keys[0],r=races[featured],rec=record(featured);return `<article class="mt-7"><p class="mb-3 text-[10px] font-semibold tracking-wider text-muted">${rec.dates.length?'ON YOUR RADAR':'ONE FOR YOUR RADAR'}</p><div class="relative"><button class="block w-full overflow-hidden rounded-xl" data-action="race" data-race="${featured}" aria-label="Explore ${r.name}">${r.photo?`<img src="${photo}" alt="Two runners on a Brooklyn waterfront at dawn" class="h-[145px] w-full object-cover">`:`<div class="flex h-[145px] items-end bg-[#364C35] p-5 text-4xl text-lime">25 km of fresh air.</div>`}</button><button class="absolute right-3 top-3 flex h-11 items-center gap-2 rounded-xl bg-paper px-3 text-xs" data-action="save" data-race="${featured}" aria-pressed="${rec.saved}" aria-label="${rec.saved?'Unsave':'Save'} ${r.name}">${icon(rec.saved?'bookmark-check':'bookmark','h-4 w-4')}<span>${rec.saved?'Saved':'Save'}</span></button></div><button class="mt-3 w-full text-left" data-action="race" data-race="${featured}"><span class="text-[10px] font-semibold tracking-wider text-muted">${r.shortCity.toUpperCase()} · ${r.distance.toUpperCase()}</span><h2 class="mt-1 text-[26px] font-medium tracking-tight">${r.name}</h2></button><p id="next-moment" class="mt-2 flex items-center gap-2 text-[13px] text-muted ${state.moment?'moment-change':''}"><span class="current-dot h-1.5 w-1.5 shrink-0 rounded-full bg-[#78955B]"></span>${nextMoment(featured)}</p><div class="mt-4 flex gap-2">${pokeButton(featured,'flex-1')}<button class="tactile min-h-12 flex-1 text-[13px] font-semibold" data-action="share" data-race="${featured}">We should run this ↗</button></div>${rec.dates.length?'<p class="moment-change mt-3 text-xs text-[#43572C]">You’re good. Your dates are saved.</p>':''}</article>
<button class="my-7 block w-full border-y border-line py-4 text-left" data-action="guide"><strong class="block text-base font-medium">New to race sign-ups?</strong><span class="mt-1 block text-[13px] text-muted">Here’s the easy version →</span></button><p class="mb-2 text-[10px] font-semibold tracking-wider text-muted">A COUPLE MORE YOU MIGHT LIKE</p>${keys.slice(1).map(k=>raceRow(k)).join('')}${keys.length===1?'<p class="py-4 text-sm text-muted">That looks like your kind of race.</p>':''}`;}
function raceRow(key){const r=races[key];return `<button class="race-row reveal flex min-h-[80px] w-full items-center gap-4 border-b border-line py-3 text-left" data-action="race" data-race="${key}"><span class="w-10 shrink-0 text-xs font-semibold text-muted">${r.km}</span><span class="flex-1"><span class="block text-[17px] font-medium">${r.name}</span><span class="mt-1 block text-xs text-muted">${r.shortCity} · ${r.date.replace(', 2027','')}</span></span>${icon('arrow-up-right')}</button>`;}
function hero(){const r=race();return `<header class="relative h-[240px] overflow-hidden bg-[#263E30]">${r.photo?`<img src="${photo}" alt="Runners by the Brooklyn waterfront" class="h-full w-full object-cover">`:''}<div class="absolute inset-0 bg-linear-to-t from-[#0C1714]/95 via-[#0C1714]/20 to-[#0C1714]/10"></div><div class="absolute inset-x-4 top-4 flex justify-between"><button data-action="nav" data-route="home" class="${secondary} !rounded-full !bg-paper !px-3">${icon('arrow-left','h-4 w-4')}Discover</button><button data-action="share" class="${secondary} !rounded-full !bg-paper !px-3" aria-label="Share ${r.name}">${icon('share-2','h-4 w-4')}Share</button></div><div class="absolute inset-x-4 bottom-6 text-white"><p class="text-[10px] font-semibold tracking-wider text-[#DFE9DA]">${r.city.toUpperCase()} · ${r.photo?'ROAD RACE':'TRAIL RUN'}</p><h1 tabindex="-1" class="mt-2 text-[34px] font-medium leading-none tracking-tight">${r.name}</h1><p class="mt-3 text-sm text-white/90">${r.km} · ${r.date}</p></div></header>`;}
function detail(){return `${hero()}<div class="px-4 pb-7"><div role="tablist" aria-label="Race detail view" class="sticky top-0 z-20 mt-4 grid grid-cols-3 gap-1 rounded-2xl bg-wash p-1">${['Overview','Timeline','Race info'].map(t=>`<button role="tab" tabindex="${state.tab===t?0:-1}" aria-selected="${state.tab===t}" aria-controls="race-panel" id="tab-${t.replace(' ','-')}" data-action="tab" data-tab="${t}" class="min-h-11 rounded-xl px-1 text-[13px] font-medium ${state.tab===t?'bg-ink text-white':'text-muted hover:bg-white/50'}">${t}</button>`).join('')}</div><section id="race-panel" role="tabpanel" aria-labelledby="tab-${state.tab.replace(' ','-')}" class="mt-5">${state.tab==='Overview'?overview():state.tab==='Timeline'?timeline():raceInfo()}</section><p class="mt-5 text-[10px] text-muted">Example race details · Check the organizer for updates.</p></div>`;}
function overview(){const r=race(),rec=record();return `<section><p class="text-[10px] font-semibold tracking-wider text-muted">${rec.going?'YOU’RE IN':'NEXT FOR '+r.shortCity.toUpperCase()}</p><h2 class="mt-3 text-[26px] font-medium leading-tight tracking-tight">${rec.going?'See you at the start.':state.moment&&r.lottery?'Results day is coming.':r.lottery?'Lottery entry closes':'Registration closes'}</h2><p class="mt-3 text-[15px]">${rec.going?r.date:state.moment&&r.lottery?r.results+' · Time to come':r.closes+' · '+r.time+' ET'}</p><p class="mt-3 text-[13px] leading-5 text-muted">${rec.going?'You’ve marked your entry as confirmed. We’ve turned off your entry reminders.':rec.dates.length?'You’re good. Your dates are saved here. We’ll keep the important moments together.':'We can give you a nudge before it closes. You just need to apply on the race site.'}</p><div class="mt-4">${rec.going?`<button data-action="going" class="${secondary} w-full">${icon('check')}I’m going · Edit</button>`:pokeButton(state.race)}</div><p class="mt-2 text-center text-[11px] text-muted">${rec.going?'Entry confirmed by you, not the race organizer.':'A heads-up, not a race entry.'}</p><button data-action="official" class="mt-2 flex min-h-11 w-full items-center justify-center gap-2 text-[13px] underline underline-offset-4">Apply on the race site ${icon('arrow-up-right','h-4 w-4')}</button></section>
${!rec.going?`<div class="mt-5 flex items-start gap-3"><div class="flex-1"><h3 class="text-[15px] font-medium">Already got your place?</h3><p class="mt-2 text-xs text-muted">After registration and payment.</p></div><button class="${secondary} shrink-0" data-action="going">I’m going</button></div>`:''}
<section class="reveal mt-6 border-t border-line pt-4"><h3 class="text-lg font-medium">Better with friends.</h3><button class="mt-3 flex min-h-12 w-full items-center gap-3 text-left" data-action="friends"><span class="flex gap-1.5"><span class="flex h-[38px] w-[38px] items-center justify-center rounded-full bg-soft text-xs font-semibold text-[#43572C]">ML</span><span class="flex h-[38px] w-[38px] items-center justify-center rounded-full bg-wash text-xs font-semibold text-[#43572C]">AC</span></span><span class="flex-1"><strong class="block text-sm font-semibold">Maya and Alex</strong><span class="block text-xs text-muted">are going to this race too</span></span>${icon('chevron-right','h-4 w-4')}</button><p class="mt-2 text-[11px] text-muted">Plans shared by your friends. Example people.</p><button class="${secondary} mt-4 w-full" data-action="share">${icon('share-2')}We should run this</button></section><section class="reveal mt-5 border-t border-line pt-4"><p class="text-[10px] font-semibold tracking-wider text-muted">THE RUN</p><p class="mt-2 text-sm leading-6 text-muted">${r.story}</p></section>`;}
function milestones(){const r=race();const list=[{id:'opens',title:'Entries open',date:r.opens+' · 9 AM',short:r.opens.split(',')[0],hint:'You can send your application.',icon:'calendar-plus'}, {id:'closes',title:'Entries close',date:r.closes+' · '+r.time,short:r.closes.split(',')[0],hint:'Send it on the race site. We can remind you.',icon:'alarm-clock'}];if(r.lottery)list.push({id:'results',title:'Results day',date:r.results+' · Time to come',short:r.results.split(',')[0],hint:'Check your email to see if you got a place.',icon:'mail'});list.push({id:'confirm',title:'Make it official',date:'Date to come · If you’re picked',short:'If picked',hint:'Finish any forms or payment.',icon:'badge-check'},{id:'bib',title:'Pick up your bib',date:'Details to come',short:'To come',hint:'We’ll add the where and when here.',icon:'ticket'},{id:'race',title:'Run '+r.shortCity,date:r.date+' · Start time to come',short:r.date.split(',')[0],hint:'Your next finish line. Bring a friend.',icon:'flag'});return list;}
function timeline(){const all=milestones(),track=all.filter(x=>x.id!=='bib'),next=state.moment&&race().lottery?'results':'closes';return `<h2 class="text-[22px] font-medium">The road to race day.</h2><p class="mt-2 text-xs text-muted">Poke the dates you want a nudge for.</p><div class="mt-5 grid grid-cols-${track.length} relative"><div class="timeline-track absolute inset-x-7 top-[42px] h-[3px] bg-line"></div>${track.map(m=>`<button class="relative z-10 flex min-h-[100px] flex-1 flex-col items-center gap-2 text-[10px]" data-action="milestone" data-id="${m.id}" aria-label="${m.title}, ${m.date}">${icon(m.icon,'h-[18px] w-[18px] text-muted')}<span class="mt-1 h-3 w-3 rounded-full ${m.id===next?'current-dot border border-ink bg-lime':'border border-[#B5BCAF] bg-paper'}"></span><span class="mt-1 ${m.id===next?'font-semibold':''}">${({opens:'Opens',closes:'Closes',results:'Results',confirm:'Confirm',race:'Race day'})[m.id]}</span><span class="text-muted">${m.short}</span></button>`).join('')}</div><p class="text-[10px] text-muted">Example: 2026 → 2027 · Steps, not a time scale</p><h3 class="mb-2 mt-6 text-xl font-medium">Here’s what happens.</h3><p class="mb-3 text-[11px] text-muted">All times Eastern</p><div>${all.map(m=>`<div id="milestone-${m.id}" tabindex="-1" class="milestone-row reveal relative border-b border-line py-4 pl-6"><span class="absolute left-0 top-6 h-2.5 w-2.5 rounded-full ${m.id===next?'bg-lime ring-1 ring-ink':'bg-wash ring-1 ring-[#A6AE9F]'}"></span><h4 class="text-base font-medium">${m.title}</h4><p class="mt-1 text-xs ${m.id===next?'font-semibold':''} text-muted">${m.date}</p><p class="mt-1 text-xs leading-5 text-muted">${m.hint}</p></div>`).join('')}</div><div class="mt-5">${pokeButton(state.race)}</div><button data-action="share" class="min-h-11 w-full text-[13px] font-semibold">Send a friend the dates ↗</button>`;}
function raceInfo(){const r=race();return `<details open class="border-b border-line pb-4"><summary class="flex min-h-11 items-center gap-3 text-lg font-medium">${icon('ticket')}<span class="flex-1">How to get in</span>${icon('chevron-down','chevron h-4 w-4')}</summary><div class="accordion-content mt-3"><h3 class="text-[15px] font-semibold">${r.lottery?'This one uses a lottery.':'This one uses direct entry.'}</h3><p class="mt-3 text-[13px] leading-5 text-muted">${r.lottery?'Apply first. Runners are picked at random. If you get a place, finish the registration.':'Sign up on the race site while places are available. Complete any required forms and payment.'}</p><dl class="mt-4 grid grid-cols-2 gap-5"><div><dt class="text-[11px] text-muted">Race day</dt><dd class="mt-1 text-sm font-semibold">${r.date}</dd></div><div><dt class="text-[11px] text-muted">Entry fee</dt><dd class="mt-1 text-[13px] font-medium">Check the race site</dd></div></dl><button class="mt-3 flex min-h-11 w-full items-center justify-between text-[13px] font-semibold" data-action="tab" data-tab="Timeline">See the dates in Timeline ${icon('arrow-right','h-4 w-4')}</button></div></details><section class="border-b border-line py-5"><h3 class="text-lg font-medium">The run itself</h3><p class="mt-3 text-[13px]">${r.km} · ${r.photo?'Road':'Trail'} · ${r.shortCity}</p><p class="mt-3 text-[13px] text-muted">Course and weather details, closer to race day.</p><button data-action="official" class="mt-2 min-h-11 text-[13px] font-semibold">See the official course ↗</button></section>${[['Other ways in','Qualifying times, charity & more','Some races offer time-based or charity entry. A qualifying time means finishing a previous race under the organizer’s limit. Charity entry may involve a fundraising commitment. Check the rules for your route.'],['Race-weekend plans','Bib pickup and start details, when they’re ready.','Check the pickup location and hours, required ID, start time and your wave. These details are not yet verified for this example.']].map(([title,sub,body])=>`<details class="border-b border-line py-3"><summary class="flex min-h-14 items-center gap-3"><span class="flex-1"><strong class="block text-base font-medium">${title}</strong><span class="mt-1 block text-xs text-muted">${sub}</span></span>${icon('chevron-down','chevron h-4 w-4')}</summary><p class="accordion-content mt-3 text-[13px] leading-6 text-muted">${body}</p></details>`).join('')}<button data-action="official" class="mt-3 min-h-11 w-full text-left text-[13px] font-semibold">Everything else, from the organizer ↗</button>`;}
function calendar(){const first=new Date(state.year,state.month,1).getDay(),days=new Date(state.year,state.month+1,0).getDate();const monthLabel=new Date(state.year,state.month,1).toLocaleDateString('en-US',{month:'long',year:'numeric'});const events=state.month===9&&state.year===2026?{2:'Entries open · 9 AM ET',16:'Entry closes · 5 PM ET',28:'Lottery results · Time to come'}:{};return `<div class="px-4 pb-5">${appHeader()}<h1 tabindex="-1" class="mt-2 text-[28px] font-medium tracking-tight">Your next few dates.</h1><p class="mt-2 text-[13px] text-muted">A little heads-up, right when you need it.</p><section class="mt-7 flex items-center gap-3 border-b border-line pb-5"><div class="flex-1"><p class="text-[10px] font-semibold tracking-wider text-muted">NEXT FOR YOU</p><h2 class="mt-2 text-[22px]">Brooklyn Half</h2><p class="mt-2 text-xs text-muted">Entry closes Oct 16 · 5 PM ET</p></div>${pokeButton('brooklyn','!px-3 !text-xs')}</section><div class="my-4 flex items-center justify-between"><h2 class="text-lg font-medium">${monthLabel}</h2><div class="flex"><button data-action="month" data-delta="-1" class="flex h-11 w-11 items-center justify-center" aria-label="Previous month">${icon('chevron-left')}</button><button data-action="month" data-delta="1" class="flex h-11 w-11 items-center justify-center" aria-label="Next month">${icon('chevron-right')}</button></div></div><div class="grid grid-cols-7 text-center">${['S','M','T','W','T','F','S'].map(d=>`<span class="py-2 text-xs text-muted">${d}</span>`).join('')}${Array.from({length:first},()=>'<span></span>').join('')}${Array.from({length:days},(_,i)=>`<button data-action="day" data-day="${i+1}" aria-label="${monthLabel} ${i+1}${events[i+1]?', '+events[i+1]:''}" aria-pressed="${state.day===i+1}" class="flex min-h-11 flex-col items-center justify-center gap-1 rounded-xl text-sm ${state.day===i+1?'bg-ink text-white':'hover:bg-wash'}"><span>${i+1}</span><span class="h-1 w-1 rounded-full ${events[i+1]?state.day===i+1?'bg-lime':'bg-[#56762C]':'bg-transparent'}"></span></button>`).join('')}</div><p class="mt-4 text-[10px] text-muted">● Race moments · Example dates in Eastern time</p><section id="calendar-event" aria-live="polite" class="moment-change mt-6 border-t border-line pt-5"><p class="text-[10px] font-semibold uppercase tracking-wider text-muted">${new Date(state.year,state.month,state.day).toLocaleDateString('en-US',{weekday:'long',month:'long',day:'numeric'})}</p>${events[state.day]?`<button class="mt-3 w-full text-left" data-action="race" data-race="brooklyn"><h3 class="text-lg font-medium">Brooklyn Half</h3><p class="mt-1 text-[13px] text-muted">${events[state.day]}</p></button><button data-action="share" data-race="brooklyn" class="mt-4 flex min-h-11 items-center gap-3 text-[13px]">${icon('share-2')}Send a friend the date</button>`:'<h3 class="mt-3 text-lg">Nothing to keep track of here.</h3><p class="mt-2 text-[13px] text-muted">A good day to just go for a run.</p>'}</section></div>`;}
function savedPage(reminders=false){const keys=Object.keys(races).filter(k=>reminders?record(k).dates.length:record(k).saved||record(k).dates.length||record(k).going);return `<div class="px-4 pb-6">${appHeader()}<h1 tabindex="-1" class="mt-3 text-[28px] font-medium">${reminders?'Your little heads-ups.':'Races on your radar.'}</h1><p class="mt-3 text-sm text-muted">${reminders?'Just the races you chose. Always your call.':'A few start lines to daydream about.'}</p>${keys.length?keys.map(k=>`<div class="mt-5">${raceRow(k)}${reminders?`<p class="mt-3 text-xs text-muted">${record(k).dates.length} dates saved · ${record(k).dates.includes('closes')?'24 hours + 1 hour before closing':'At the announced time'}</p><div class="mt-3">${pokeButton(k)}</div>`:''}</div>`).join(''):`<div class="py-14"><div class="mb-5 flex h-12 w-12 items-center justify-center rounded-full bg-soft">${icon(reminders?'bell':'bookmark')}</div><h2 class="text-xl">Your next race is out there.</h2><p class="mt-3 text-sm leading-6 text-muted">${reminders?'Poke a race and we’ll keep its dates here.':'Find a race you like, then save it for later.'}</p><button data-action="nav" data-route="home" class="${primary} mt-6">Find a race ${icon('arrow-right')}</button></div>`}</div>`;}
function onboarding(){const step=state.step;return `<div class="flex min-h-[calc(100dvh-60px)] flex-col px-4 pb-6 min-[701px]:min-h-[790px]"><header class="flex min-h-20 items-center justify-between">${step?'<button data-action="onboard-back" class="flex min-h-11 items-center gap-2 text-sm">'+icon('arrow-left','h-4 w-4')+'Back</button>':'<span class="text-[22px] font-extrabold">race poke.</span>'}<button data-action="nav" data-route="home" class="min-h-11 px-3 text-sm text-muted">Skip</button></header><div class="mb-6 grid grid-cols-3 gap-1.5" aria-label="Step ${step+1} of 3">${[0,1,2].map(i=>`<div class="h-1 rounded-full ${i<=step?'bg-ink':'bg-line'}"></div>`).join('')}</div><div class="flex-1"><p class="text-[10px] font-semibold tracking-wider text-muted">${step+1} OF 3 · ${['HELLO, RUNNER','YOUR KIND OF RUN','A LITTLE NUDGE'][step]}</p><h1 tabindex="-1" class="mt-3 text-[32px] leading-[1.1] tracking-tight">${['You find the race.<br>We mind the dates.','What sounds<br>like a good run?','A running friend<br>in your pocket.'][step]}</h1><p class="mt-4 text-sm leading-6 text-muted">${['Find something worth running. Poke it, and we’ll give you a heads-up when it’s time.','A city and a distance. We’ll take it from there.','A quiet heads-up for the races you Poke. That’s it.'][step]}</p>${step===0?`<div class="mt-8"><p class="text-[10px] font-semibold tracking-wider text-muted">MAYBE THIS IS YOUR NEXT ONE</p><h2 class="mt-3 text-[28px]">Brooklyn Half</h2><p class="mt-2 text-xs text-muted">May 16, 2027 · Brooklyn, NY</p><div class="reveal mt-5 flex items-center gap-3 rounded-xl bg-soft p-4">${icon('bell')}<div><strong class="block text-sm font-medium">A little heads-up.</strong><p class="mt-1 text-xs text-muted">Brooklyn opens tomorrow at 9 AM ET.</p></div></div><p class="mt-5 text-center text-xs text-muted">Less date-checking. More daydreaming.</p></div>`:step===1?`<div class="mt-7"><label class="text-sm font-semibold" for="onboard-city">Where would you like to run?</label><input id="onboard-city" class="mt-3 h-12 w-full rounded-xl border border-line bg-white px-4 text-sm" value="${escapeHTML(state.city)}"><p class="mt-2 text-xs text-muted">Pick a city — no location access needed.</p><h2 class="mt-7 text-sm font-semibold">How far are you thinking?</h2><p class="mt-2 text-xs text-muted">Pick a few. Dream a little.</p><div class="mt-4 grid grid-cols-2 gap-3">${['5K','10K','Half marathon','Marathon','Trail & ultra','Any distance'].map(d=>`<button data-action="onboard-distance" data-distance="${d}" aria-pressed="${state.onboardDistances.includes(d)}" class="min-h-12 rounded-xl border px-2 text-[13px] ${state.onboardDistances.includes(d)?'border-[#9AAF83] bg-soft':'border-line bg-white'}">${d}${state.onboardDistances.includes(d)?' ✓':''}</button>`).join('')}</div></div>`:`<div class="reveal mt-7 rounded-xl bg-soft p-5"><p class="flex items-center gap-2 text-sm font-semibold">${icon('bell')}race poke.</p><h2 class="mt-5 text-xl">Brooklyn opens tomorrow.</h2><p class="mt-2 text-sm text-muted">9 AM ET. Your next start line is calling.</p></div><div class="mt-7 space-y-5">${[['bell-off','Only the races you Poke','No noise about races you didn’t choose.'],['sliders-horizontal','Always your call','Change or stop reminders anytime.']].map(([i,t,d])=>`<div class="flex gap-3">${icon(i,'mt-1 h-5 w-5 shrink-0 text-[#43572C]')}<div><h3 class="text-sm font-semibold">${t}</h3><p class="mt-1 text-xs text-muted">${d}</p></div></div>`).join('')}</div><p class="mt-5 text-xs text-muted">Demo only. No device permission is requested here.</p>`}</div><footer class="mt-10"><button data-action="onboard-next" class="${primary} w-full">${['Let’s find a race','Continue','Turn on notifications'][step]}${step<2?icon('arrow-right'):''}</button><p class="mt-3 text-center text-xs text-muted">${['No account needed to have a look.','Nothing’s set in stone.',''][step]}</p>${step===2?'<button data-action="nav" data-route="home" class="min-h-11 w-full text-sm">Maybe later</button>':''}</footer></div>`;}
function render(){const view=$('#view');view.innerHTML=state.route==='home'?home():state.route==='detail'?detail():state.route==='calendar'?calendar():state.route==='onboarding'?onboarding():savedPage(state.route==='reminders');$('#navigation').hidden=state.route==='onboarding';$('#navigation').innerHTML=[['home','compass','Discover'],['saved','bookmark','Saved'],['calendar','calendar-days','Calendar'],['reminders','bell','Reminders']].map(([r,i,l])=>`<button data-action="nav" data-route="${r}" class="flex min-h-14 flex-1 flex-col items-center justify-center gap-1 rounded-xl text-[10px] ${state.route===r?'bg-lime font-semibold':'hover:bg-wash'}" aria-current="${state.route===r?'page':'false'}">${icon(i,'h-5 w-5')}<span>${l}</span></button>`).join('');$('#navigation').classList.add('flex','gap-1');bindVisuals();}
function sheetFrame(title, body, raceContext=true){return `<div id="drag-handle" class="mx-auto mb-4 flex h-4 w-20 cursor-grab items-start justify-center" aria-hidden="true"><span class="h-1 w-9 rounded-full bg-[#BCC3B5]"></span></div><div class="flex items-center gap-3"><div class="flex-1">${raceContext?`<p class="text-[10px] font-semibold tracking-wider text-muted">${race().name.toUpperCase()}</p>`:''}<h2 id="sheet-title" class="mt-1 text-[26px] font-medium tracking-tight">${title}</h2></div><button data-action="close" class="flex h-11 w-11 items-center justify-center rounded-full hover:bg-wash" aria-label="Close sheet">${icon('x')}</button></div>${body}<div class="mx-auto mt-5 h-1 w-[120px] rounded-full bg-ink" aria-hidden="true"></div>`;}
function reminderSheet(){const r=race(),options=[];if(!r.lottery)options.push({id:'opens',title:'Registration opens',date:r.opens+' · 9:00 AM',hint:'24 hours + 1 hour before, and when it opens'});options.push({id:'closes',title:'Entry closes',date:r.closes+' · '+r.time,hint:'24 hours + 1 hour before'});if(r.lottery)options.push({id:'results',title:'Find out if you’re in',date:r.results+' · Time not announced',hint:'At the announced time'});return sheetFrame('Poke these dates',`<p class="mt-3 text-[13px] text-muted">Pick your dates. We’ll handle the timing.</p><form id="reminder-form"><p class="mt-5 text-[10px] font-semibold tracking-wider text-muted">EXAMPLE DATES · EASTERN TIME (ET)</p><div class="mt-2">${options.map(o=>`<label class="flex min-h-20 cursor-pointer items-center gap-3 border-b border-line py-3"><input type="checkbox" name="date" value="${o.id}" ${state.draft.includes(o.id)?'checked':''} class="h-5 w-5 shrink-0 accent-[#1D1F1B]"><span><strong class="block text-sm font-semibold">${o.title}</strong><span class="mt-1 block text-xs text-muted">${o.date}</span><span class="mt-1 block text-[11px] text-[#43572C]">${o.hint}</span></span></label>`).join('')}</div><button type="submit" id="save-reminders" class="${primary} mt-5 w-full" ${state.draft.length?'':'disabled'}>Poke me about these dates</button><p id="selection-count" aria-live="polite" class="mt-3 text-center text-xs text-muted">${state.draft.length} dates · Change your mind anytime</p><p class="mt-2 text-center text-[10px] text-muted">Saved in this demo only. No real notifications sent.</p>${record().dates.length?'<button type="button" data-action="remove-reminders" class="mt-2 min-h-11 w-full text-xs text-muted underline underline-offset-4">Stop these reminders</button>':''}</form>`);}
function shareSheet(){return sheetFrame('We should run this.',`<p class="mt-3 text-sm text-muted">Send a little possibility to your running buddy.</p><div class="my-5 border-y border-line py-4"><p class="text-lg font-medium">${race().name}</p><p class="mt-1 text-xs text-muted">${race().date} · ${race().km}</p><p class="mt-4 text-sm leading-6">“We should run ${race().name} together!”</p></div><button class="${primary} w-full" data-action="native-share">${icon('share-2')}Share with a friend</button><button class="${secondary} mt-3 w-full" data-action="copy-link">${icon('link')}Copy race link</button><p class="mt-3 text-center text-[11px] text-muted">Sharing doesn’t register anyone or mark them as going.</p>`);}
function goingSheet(){const going=record().going;return sheetFrame(going?'Plans changed?':'Got your place?',`<p class="mt-4 text-sm leading-6 text-muted">${going?'You marked your entry as confirmed. You can change that here.':'Use this after your registration and any required payment are complete—not just after entering the lottery.'}</p><p class="mt-3 text-sm leading-6 text-muted">${going?'Your reminders stay off until you choose to Poke again.':'We’ll turn off entry reminders for this race. This won’t register you with the organizer.'}</p><button data-action="confirm-going" class="${primary} mt-6 w-full">${going?'I’m not going after all':'Yes, I’m going'}</button><button data-action="close" class="mt-2 min-h-11 w-full text-sm">${going?'Keep my status':'Not yet'}</button>`);}
function guideSheet(){return sheetFrame('Here’s the easy version.',`<div class="mt-5 space-y-5">${[['Find your race','Something you’d love to run.'],['Check the way in','Lottery? Apply and wait to be picked. Direct entry? Sign up while places remain. Other routes may need a past race time or a fundraising commitment.'],['Poke the dates','We’ll keep openings, deadlines and results together.'],['Apply on the race site','Race Poke reminds you; the organizer handles your entry.'],['Make it official','If accepted, complete any forms and payment. Then tell us you’re going.']].map(([t,d],i)=>`<div class="flex gap-3"><span class="text-xs text-muted">0${i+1}</span><div><h3 class="text-base font-medium">${t}</h3><p class="mt-1 text-[13px] leading-5 text-muted">${d}</p></div></div>`).join('')}</div><button data-action="close" class="${primary} mt-6 w-full">Got it. Let’s find a race.</button>`,false);}
function settingsSheet(){return sheetFrame('Try a little motion.',`<div class="mt-5 divide-y divide-line"><label class="flex min-h-14 items-center justify-between text-sm"><span>Reduce motion</span><input id="mobile-motion" type="checkbox" ${state.motion?'checked':''} class="h-5 w-5 accent-[#1D1F1B]"></label><button data-action="next-moment" class="min-h-14 w-full text-left text-sm">Try the next race moment →</button><button data-action="onboarding" class="min-h-14 w-full text-left text-sm">Try onboarding →</button><button data-action="reset" class="min-h-14 w-full text-left text-sm">Reset this demo →</button></div><p class="mt-4 text-xs leading-5 text-muted">Interactive prototype. Choices stay on this device. No actual reminders, registration or automatic messages are sent.</p>`,false);}
function openSheet(kind){clearTimeout(closeTimer);clearTimeout(toastTimer);$('#toast').hidden=true;$('#toast').classList.remove('visible');lastFocus=document.activeElement;state.modal=kind;if(kind==='poke'){if(record().going){toast('You’re marked as going. Change your status to set entry reminders.');state.modal=null;return;}state.draft=[...(record().dates.length?record().dates:race().lottery?['closes','results']:['opens','closes'])];}
const content=kind==='poke'?reminderSheet():kind==='share'?shareSheet():kind==='going'?goingSheet():kind==='guide'?guideSheet():kind==='settings'?settingsSheet():kind==='friends'?sheetFrame('Company at the start.',`<div class="mt-5 space-y-4">${[['ML','Maya Lewis'],['AC','Alex Chen']].map(([a,n])=>`<div class="flex min-h-14 items-center gap-3"><span class="flex h-10 w-10 items-center justify-center rounded-full bg-soft text-xs font-semibold">${a}</span><span><strong class="block text-sm">${n}</strong><span class="block text-xs text-muted">Marked themselves as going</span></span></div>`).join('')}</div><p class="mt-4 text-xs text-muted">Example friends, not verified race entries.</p><button data-action="share" class="${primary} mt-5 w-full">Invite your running buddy</button>`):kind==='official'?sheetFrame('The race site takes it from here.',`<p class="mt-4 text-sm leading-6 text-muted">In the real app, this opens the organizer’s verified registration page. This race schedule is illustrative, so this demo won’t send you to an unverified entry form.</p><button data-action="close" class="${primary} mt-6 w-full">Got it</button>`):kind==='city-filter'?sheetFrame('Where sounds good?',`<label for="city-input" class="mt-5 block text-sm">City or region</label><input id="city-input" class="mt-2 h-12 w-full rounded-xl border border-line bg-white px-4" value="${escapeHTML(state.city)}"><button data-action="apply-city" class="${primary} mt-5 w-full">Use this city</button><p class="mt-3 text-xs text-muted">This demo includes New York and Hudson Valley races.</p>`,false):sheetFrame('How far are you thinking?',`<div class="mt-5 grid grid-cols-2 gap-3">${['Any distance','5K','10K','Half marathon','Marathon','Trail & ultra'].map(d=>`<button data-action="apply-distance" data-distance="${d}" class="min-h-12 rounded-xl border ${state.distance===d?'border-[#9AAF83] bg-soft':'border-line bg-white'} px-2 text-sm">${d}</button>`).join('')}</div>`,false);
$('#sheet').innerHTML=content;$('#overlay').hidden=false;$('#shell').inert=true;$('aside').inert=true;refreshIcons();requestAnimationFrame(()=>requestAnimationFrame(()=>{$('#overlay').classList.add('open');$('#sheet').focus({preventScroll:true});}));bindDrag();}
function closeSheet(restore=true){if(!state.modal)return;state.modal=null;$('#overlay').classList.remove('open');clearTimeout(closeTimer);closeTimer=setTimeout(()=>{$('#overlay').hidden=true;$('#shell').inert=false;$('aside').inert=false;if(restore&&lastFocus?.isConnected)lastFocus.focus({preventScroll:true});else if(document.activeElement===$('#sheet')||$('#sheet').contains(document.activeElement)||document.activeElement===document.body){const target=state.route==='detail'?$('#view h1'):$('.poke-button')||$('#view h1');target?.focus({preventScroll:true});}},reduced()?0:260);}
function bindDrag(){const handle=$('#drag-handle');let start=null;handle?.addEventListener('pointerdown',e=>{start=e.clientY;handle.setPointerCapture(e.pointerId);});handle?.addEventListener('pointerup',e=>{if(start!==null&&e.clientY-start>55)closeSheet();start=null;});handle?.addEventListener('pointercancel',()=>start=null);}
function afterStateChange(){const scroll=$('#screen').scrollTop;render();$('#screen').scrollTop=scroll;}
function smoothTo(target){const scroller=$('#screen'),from=scroller.scrollTop,to=target.offsetTop-$('#view').offsetTop-20;if(reduced()){scroller.scrollTop=to;target.focus({preventScroll:true});return;}const start=performance.now();function tick(now){const t=Math.min((now-start)/220,1);scroller.scrollTop=from+(to-from)*(1-Math.pow(1-t,3));if(t<1)requestAnimationFrame(tick);else target.focus({preventScroll:true});}requestAnimationFrame(tick);}
async function copyLink(){const url=new URL(location.href);url.search='?race='+state.race;try {await navigator.clipboard.writeText(url.href);closeSheet();toast('Link copied. Send it to your running buddy.');}catch {const field=document.createElement('input');field.readOnly=true;field.value=url.href;field.className='mt-4 w-full rounded-lg border border-line bg-white p-3 text-xs';field.setAttribute('aria-label','Race link to copy');$('#sheet').append(field);field.select();toast('Select and copy the race link below.');}}
async function nativeShare(){const url=new URL(location.href);url.search='?race='+state.race;if(!navigator.share){await copyLink();return;}try{await navigator.share({title:race().name,text:`We should run ${race().name} together!`,url:url.href});closeSheet();toast('A little possibility, shared.');}catch(err){if(err.name!=='AbortError')await copyLink();}}
document.addEventListener('click',async e=>{const el=e.target.closest('[data-action]');if(!el)return;const a=el.dataset.action;if(el.dataset.race)state.race=el.dataset.race;
if(a==='nav')route(el.dataset.route);
else if(a==='race')route('detail',{race:el.dataset.race,tab:'Overview'});
else if(a==='poke')openSheet('poke');
else if(['share','going','guide','friends','official','settings','city-filter','distance-filter'].includes(a))openSheet(a);
else if(a==='close')closeSheet();
else if(a==='tab'){const scroll=$('#screen').scrollTop;state.tab=el.dataset.tab;$('#view').classList.remove('arriving');render();$('#screen').scrollTop=Math.min(scroll,250);$('#race-panel').classList.add('arriving');$('#tab-'+state.tab.replace(' ','-'))?.focus({preventScroll:true});}
else if(a==='save'){patch({saved:!record().saved});afterStateChange();toast(record().saved?'Saved for a little daydreaming.':'Race removed from your saved list.');}
else if(a==='copy-link')await copyLink();
else if(a==='native-share')await nativeShare();
else if(a==='confirm-going'){const going=!record().going;patch({going,dates:[],saved:going||record().saved});closeSheet(false);afterStateChange();toast(going?'You’re going. Entry reminders are off.':'Status updated. Poke again if you need a nudge.');}
else if(a==='remove-reminders'){patch({dates:[]});closeSheet(false);afterStateChange();toast('Reminders off. You can Poke again anytime.');}
else if(a==='apply-distance'){state.distance=el.dataset.distance;closeSheet(false);afterStateChange();}
else if(a==='apply-city'){state.city=$('#city-input').value.trim()||'New York';closeSheet(false);afterStateChange();toast('City preference updated for this demo.');}
else if(a==='clear-search'){state.search='';state.distance='Any distance';render();}
else if(a==='milestone'){const row=$('#milestone-'+el.dataset.id);if(row){row.classList.add('bg-soft');smoothTo(row);setTimeout(()=>row.classList.remove('bg-soft'),1800);}}
else if(a==='month'){state.month+=Number(el.dataset.delta);if(state.month<0){state.month=11;state.year--;}if(state.month>11){state.month=0;state.year++;}state.day=1;afterStateChange();}
else if(a==='day'){state.day=Number(el.dataset.day);const scroll=$('#screen').scrollTop;render();$('#screen').scrollTop=scroll;$(`[data-action="day"][data-day="${state.day}"]`)?.focus({preventScroll:true});}
else if(a==='next-moment'){closeSheet(false);state.moment=1-state.moment;state.race='brooklyn';state.route='home';render();$('#next-moment')?.classList.add('moment-change');toast(state.moment?'Demo jumped to results day.':'Demo returned to the entry deadline.');}
else if(a==='onboarding'){state.step=0;route('onboarding');}
else if(a==='onboard-back'){state.step=Math.max(0,state.step-1);render();$('#screen').scrollTop=0;}
else if(a==='onboard-next'){if(state.step===1)state.city=$('#onboard-city').value.trim()||'New York';if(state.step<2){state.step++;render();$('#view').classList.add('arriving');$('#screen').scrollTop=0;}else{route('home');toast('You’re ready. Pick a race to Poke.');}}
else if(a==='onboard-distance'){const d=el.dataset.distance;state.onboardDistances=state.onboardDistances.includes(d)?state.onboardDistances.filter(x=>x!==d):[...state.onboardDistances,d];const city=$('#onboard-city')?.value;if(city)state.city=city;afterStateChange();}
else if(a==='reset'){closeSheet(false);state.records={};state.moment=0;state.route='home';state.tab='Overview';state.race='brooklyn';state.search='';state.distance='Any distance';save();render();$('#screen').scrollTop=0;toast('A fresh start. Try a Poke.');}
});
document.addEventListener('submit',e=>{if(e.target.id!=='reminder-form')return;e.preventDefault();const dates=$$('input[name="date"]:checked',$('#sheet')).map(el=>el.value);if(!dates.length)return;patch({dates,saved:true,going:false});state.justPoked=state.race;closeSheet(false);afterStateChange();toast('Poked. Your dates are saved here.');setTimeout(()=>{$$('.poke-button.just-poked').forEach(b=>{b.classList.remove('just-poked');void b.offsetWidth;b.classList.add('just-poked');});},reduced()?0:270);setTimeout(()=>{state.justPoked=null;},650);});
document.addEventListener('change',e=>{if(e.target.matches('input[name="date"]')){state.draft=$$('input[name="date"]:checked',$('#sheet')).map(el=>el.value);$('#save-reminders').disabled=!state.draft.length;$('#selection-count').textContent=`${state.draft.length} ${state.draft.length===1?'date':'dates'} · Change your mind anytime`;}
if(['motion-setting','mobile-motion'].includes(e.target.id)){state.motion=e.target.checked;save();applyMotion();activateReveals();}});
document.addEventListener('input',e=>{if(e.target.id==='race-search'){state.search=e.target.value;$('#home-results').innerHTML=homeResults();bindVisuals();}});
document.addEventListener('keydown',e=>{if(state.modal){if(e.key==='Escape'){e.preventDefault();closeSheet();return;}if(e.key==='Tab'){const focusable=$$('button:not(:disabled), input:not(:disabled), a[href], [tabindex="0"]',$('#sheet'));const first=focusable[0],last=focusable.at(-1);if(e.shiftKey&&(document.activeElement===first||document.activeElement===$('#sheet'))){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}}else if(e.target.matches('[role="tab"]')&&['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();const tabs=$$('[role="tab"]'),i=tabs.indexOf(e.target),next=e.key==='Home'?0:e.key==='End'?tabs.length-1:(i+(e.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length;tabs[next].click();}});
$('#scrim').addEventListener('click',()=>closeSheet());
reduceQuery.addEventListener('change',()=>activateReveals());
render();
